		const region = crop ?? { x: 0, y: 0, width: 2048, height: 1024 };
		return { image, width: region.width / 2, height: region.height / 2,
			sourceWidth: 2048, sourceHeight: 1024, region, scaleX: 2, scaleY: 2 };
	},
